alter table public.quests add column if not exists path_skill_id text references public.skills(id);
alter table public.quests add column if not exists path_level integer check(path_level between 1 and 3);
alter table public.quests add column if not exists prerequisite_quest_id text references public.quests(id);
alter table public.quest_steps add column if not exists verification_type text not null default 'github_file' check(verification_type in ('github_file','github_workflow','manual'));
alter table public.user_quests add column if not exists repository_url text;
create table if not exists public.user_quest_steps (user_quest_id uuid not null references public.user_quests(id) on delete cascade,quest_step_id text not null references public.quest_steps(id) on delete cascade,verified_at timestamptz,verified_commit text,verification_message text,primary key(user_quest_id,quest_step_id));
alter table public.user_quest_steps enable row level security;
create policy user_quest_steps_owner_read on public.user_quest_steps for select to authenticated using(exists(select 1 from public.user_quests u where u.id=user_quest_id and u.user_id=auth.uid()));
create or replace function public.verify_quest_step(p_quest_id text,p_step_id text,p_repository_url text,p_passed boolean,p_commit text,p_message text) returns void language plpgsql security definer set search_path=public as $$ declare u uuid:=auth.uid(); q public.user_quests%rowtype; begin if u is null then raise exception 'not authenticated'; end if; insert into user_quests(user_id,quest_id,status,repository_url) values(u,p_quest_id,'active',p_repository_url) on conflict(user_id,quest_id) do update set repository_url=excluded.repository_url returning * into q; insert into user_quest_steps(user_quest_id,quest_step_id,verified_at,verified_commit,verification_message) values(q.id,p_step_id,case when p_passed then now() else null end,case when p_passed then p_commit else null end,p_message) on conflict(user_quest_id,quest_step_id) do update set verified_at=excluded.verified_at,verified_commit=excluded.verified_commit,verification_message=excluded.verification_message; end $$;
grant execute on function public.verify_quest_step(text,text,text,boolean,text,text) to authenticated;
